{
  "provider": "openai",
  "timestamp": "<timestamp>",
  "request": {
    "url": "https://api.openai.test/v1/chat/completions",
    "method": "POST",
    "headers": {
      "Authorization": "[REDACTED]"
    },
    "transport": {
      "type": "http"
    },
    "body": {
      "model": "gpt-4o",
      "messages": [
        {
          "role": "system",
          "content": "You are a terse assistant."
        },
        {
          "role": "user",
          "content": "weather in Paris?"
        }
      ],
      "stream": false,
      "tools": [
        {
          "type": "function",
          "function": {
            "name": "get_weather",
            "description": "Weather lookup",
            "parameters": {
              "type": "object",
              "properties": {
                "city": {
                  "type": "string"
                }
              },
              "required": [
                "city"
              ]
            }
          }
        },
        {
          "type": "function",
          "function": {
            "name": "read_file",
            "description": "Read a file",
            "parameters": {
              "type": "object",
              "properties": {
                "path": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        }
      ],
      "tool_choice": "auto"
    }
  }
}

