      "messages": [
        {
          "role": "system",
          "content": "You are a terse assistant."
        },
        {
          "role": "user",
          "content": "weather in Paris and London?"
        },
        {
          "role": "assistant",
          "tool_calls": [
            {
              "id": "call_1",
              "type": "function",
              "function": {
                "name": "get_weather",
                "arguments": "{\"city\":\"Paris\"}"
