          "role": "tool",
          "content": "status:\nsuccess\n\ntoolName:\nget_weather\n\nerror:\n\n\noutput:\n{\n  \"temp\": 21\n}",
          "tool_call_id": "call_1"
        },
        {
          "role": "assistant",
          "tool_calls": [
            {
              "id": "call_2",
              "type": "function",
              "function": {
                "name": "get_weather",
                "arguments": "{\"city\":\"London\"}"
              }
            }
          ]
        },
        {
          "role": "tool",
          "content": "status:\nsuccess\n\ntoolName:\nget_weather\n\nerror:\n\n\noutput:\nrainy, 14C",
          "tool_call_id": "call_2"
        },
        {
          "role": "assistant",
          "content": "Paris 21C, London rainy 14C."
        },
        {
          "role": "user",
          "content": "thanks"
        }
      ],
      "stream": false,
      "tools": [
        {
          "type": "function",
